import React, { useState, useEffect } from "react";
import { contentFactory } from "../contentFactory";
import "../styles/CreateArticlesAdmin.css";

export default function CreateArticlePage() {
  const [mode, setMode] = useState("standard");
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [excerpt, setExcerpt] = useState("");
  const [image, setImage] = useState(null);
  const [category, setCategory] = useState("sport");
  const [isPremium, setIsPremium] = useState(false);
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("token");

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/channels/")
      .then((res) => res.json())
      .then((data) => setChannels(data))
      .catch(() => setChannels([]));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    const createContent = contentFactory(mode, token);

    const articleData = {
      title,
      content,
      excerpt,
      is_premium: isPremium,
      type: mode === "channel" ? "channel" : "standard",
      category: mode === "standard" ? category : undefined,
      channel: mode === "channel" ? selectedChannel : undefined,
      image,
    };

    try {
      await createContent(articleData);
      setMessage("✅ Статтю успішно створено!");
      setTitle("");
      setContent("");
      setExcerpt("");
      setImage(null);
      setIsPremium(false);
      setSelectedChannel("");
    } catch (err) {
      console.error(err);
      setMessage("❌ Не вдалося створити статтю");
    }
  };

  return (
    <div className="create-article-container">
      <h2>Створити статтю</h2>
      <form onSubmit={handleSubmit} className="create-article-form">
        <label>
          Тип статті:
          <select value={mode} onChange={(e) => setMode(e.target.value)}>
            <option value="standard">Звичайна</option>
            <option value="channel">Для каналу</option>
          </select>
        </label>

        <input
          type="text"
          placeholder="Заголовок"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />

        <textarea
          placeholder="Текст статті"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          required
        />

        <textarea
          placeholder="Короткий опис"
          value={excerpt}
          onChange={(e) => setExcerpt(e.target.value)}
        />

        {mode === "standard" && (
          <label>
            Категорія:
            <select value={category} onChange={(e) => setCategory(e.target.value)}>
              <option value="sport">Спорт</option>
              <option value="fashion">Мода</option>
              <option value="News">Новини</option>
            </select>
          </label>
        )}

        {mode === "channel" && (
          <label>
            Виберіть канал:
            <select
              value={selectedChannel}
              onChange={(e) => setSelectedChannel(e.target.value)}
            >
              <option value="">-- Оберіть канал --</option>
              {channels.map((ch) => (
                <option key={ch.id} value={ch.id}>
                  {ch.name}
                </option>
              ))}
            </select>
          </label>
        )}

        <label>
          Зображення:
          <input type="file" onChange={(e) => setImage(e.target.files[0])} />
        </label>

        <button type="submit">Створити</button>

        {message && <p className={message.includes("✅") ? "success" : "error"}>{message}</p>}
      </form>
    </div>
  );
}
